#include "companion_http.h"
#include "tom_stream.h"
#include <QCoreApplication>
#include <QFile>
#include <QSslKey>
#include <QSslSocket>
#include <QTcpServer>
#include <QTimer>
#include <iostream>
#include <stdexcept>
using namespace companion;
void check(bool b){if(!b)throw std::runtime_error("Tom HTTPS test failure");}
template<class F>void rejects(F f){bool yes=false;try{f();}catch(const std::exception&){yes=true;}check(yes);}
class Server:public QTcpServer {QSslCertificate cert_;QSslKey key_;public:bool sentFinal{};int requests{};Server(QSslCertificate c,QSslKey k):cert_(c),key_(k){}void incomingConnection(qintptr fd)override{auto* socket=new QSslSocket(this);socket->setLocalCertificate(cert_);socket->setPrivateKey(key_);socket->setPeerVerifyMode(QSslSocket::VerifyNone);check(socket->setSocketDescriptor(fd));connect(socket,&QSslSocket::disconnected,socket,&QObject::deleteLater);connect(socket,&QSslSocket::readyRead,socket,[this,socket]{auto request=socket->readAll();if(!request.startsWith("GET "))return;++requests;auto path=request.split(' ').value(1);if(path=="/v1/silent")return; /* never answers: a stream with no response must still fail */if(path=="/v1/redirect"){socket->write("HTTP/1.1 302 Found\r\nLocation: /v1/events\r\nContent-Length: 0\r\nConnection: close\r\n\r\n");socket->disconnectFromHost();return;}if(path=="/v1/revoked"){socket->write("HTTP/1.1 401 Unauthorized\r\nContent-Length: 2\r\nConnection: close\r\n\r\n{}");socket->disconnectFromHost();return;}if(path=="/v1/wrong-type"){socket->write("HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: 2\r\nConnection: close\r\n\r\n{}");socket->disconnectFromHost();return;}sentFinal=false;socket->write("HTTP/1.1 200 OK\r\nContent-Type: text/event-stream; charset=utf-8\r\nTransfer-Encoding: chunked\r\nConnection: close\r\n\r\n");auto first=QByteArray("id: 1\nevent: delta\ndata: {\"text\":\"first\"}\n\n");socket->write(QByteArray::number(first.size(),16)+"\r\n"+first+"\r\n");socket->flush();if(path=="/v1/timeout")return;QTimer::singleShot(150,socket,[this,socket]{sentFinal=true;auto final=QByteArray("id: 2\nevent: status\ndata: {\"status\":\"completed\"}\n\n");socket->write(QByteArray::number(final.size(),16)+"\r\n"+final+"\r\n0\r\n\r\n");socket->disconnectFromHost();});});socket->startServerEncryption();}};
int main(int argc,char** argv){QCoreApplication app(argc,argv);try{check(argc==3);QFile cf(argv[1]),kf(argv[2]);check(cf.open(QIODevice::ReadOnly)&&kf.open(QIODevice::ReadOnly));QSslCertificate cert(cf.readAll());QSslKey key(kf.readAll(),QSsl::Rsa);check(!cert.isNull()&&!key.isNull());Server server(cert,key);check(server.listen(QHostAddress::LocalHost,0));VerifiedHttpTransport http(VerifiedHttpTransport::ForTests{},QUrl(QString("https://127.0.0.1:%1").arg(server.serverPort())),cert);TomStream parser;bool incremental=false;auto response=http.stream("/v1/events",{},4096,1000,[&](const QByteArray& chunk){if(!server.sentFinal)incremental=true;return parser.feed(chunk,[](const TomEvent&){return true;});});check(incremental&&parser.cursor()==2&&parser.terminal()&&response.status==200&&response.body.isEmpty());int calls=0;response=http.stream("/v1/events",{},4096,1000,[&](const QByteArray&){++calls;return false;});check(calls==1&&response.stopped&&response.body.isEmpty());int before=server.requests;rejects([&]{http.stream("/v1/redirect",{},4096,1000,[&](const QByteArray&){++calls;return true;});});check(server.requests==before+1&&calls==1);response=http.stream("/v1/revoked",{},4096,1000,[&](const QByteArray&){++calls;return true;});check(response.status==401&&response.body=="{}"&&calls==1);rejects([&]{http.stream("/v1/wrong-type",{},4096,1000,[&](const QByteArray&){++calls;return true;});});check(calls==1);rejects([&]{http.stream("/v1/events",{},8,1000,[](const QByteArray&){return true;});});// A live stream that reaches its time budget ends as "expired", not as a failure: the event already received is
  // kept (cursor 1) so the caller resumes from there, instead of recording a network failure and backing off.
  TomStream partial;auto expired=http.stream("/v1/timeout",{},4096,60,[&](const QByteArray& chunk){return partial.feed(chunk,[](const TomEvent&){return true;});});check(expired.status==200&&expired.expired&&!expired.stopped&&partial.cursor()==1);
  rejects([&]{http.stream("/v1/silent",{},4096,60,[](const QByteArray&){return true;});});rejects([&]{http.request("GET","/v1/silent",{},{},4096,60);});std::cout<<"Tom incremental local HTTPS tests passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
